-- Run once if the database was created using an earlier schema.sql.
USE leave_monitor;
CREATE TABLE attendance_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','leave','holiday') NOT NULL DEFAULT 'present',time_in TIME NULL,time_out TIME NULL,remarks VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY uq_attendance_person_day(school_id,user_id,attendance_date),INDEX idx_attendance_school_day(school_id,attendance_date)) ENGINE=InnoDB;
